    println!("{} x {}", r.w, r.h);
}

impl Rect {
    fn new(w: u32, h: u32) -> Rect {
        Rect { w, h }
    }
    fn area(&self) -> u32 {
        self.w * self.h
    }
    fn grow(&mut self) {
        self.w += 1;
        self.h += 1;
    }
}

