enum Shape {
    Circle(f64),
    Rect { w: f64, h: f64 },
    Point,
}

fn area(s: &Shape) -> f64 {
    match s {
        Shape::Circle(r) => 3.14 * r * r,
        Shape::Rect { w, h } => w * h,
        Shape::Point => 0.0,
    }
}

fn safe_div(a: i32, b: i32) -> Option<i32> {
    if b == 0 { None } else { Some(a / b) }
}

fn main() {
    match safe_div(10, 2) {
        Some(x) => println!("got {}", x),
        None => println!("cannot divide"),
    }
    if let Some(x) = safe_div(8, 2) {
        println!("also {}", x);
    }
}

