fn parse_age(s: &str) -> Result<u8, String> {
    match s.parse::<u8>() {
        Ok(n) => Ok(n),
        Err(_) => Err(String::from("not a number")),
    }
}

fn add(a: &str, b: &str) -> Result<i32, std::num::ParseIntError> {
    let x = a.parse::<i32>()?;
    let y = b.parse::<i32>()?;
    Ok(x + y)
}

trait Speak {
    fn speak(&self) -> String;
}

struct Dog;
struct Cat;

impl Speak for Dog {
    fn speak(&self) -> String { String::from("Woof") }
}
impl Speak for Cat {
    fn speak(&self) -> String { String::from("Meow") }
}

fn largest<T: PartialOrd>(v: &[T]) -> &T {
    let mut best = &v[0];
    for x in v {
        if x > best {
            best = x;
        }
    }
    best
}

